// ============================================================
// Prepare TCM Source Text
// Version: phythera_tcm_source_prepare_v2
//
// Generic preparation for an approved TCM source.
// No provider-specific or plant-specific parsing.
// ============================================================

const html =
  $json.data ??
  $json.body ??
  $json.text ??
  '';


// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function decodeHtml(text) {
  return String(text ?? '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCharCode(Number(n))
    );
}


function htmlToText(value) {

  return decodeHtml(value)

    // Remove non-content elements
    .replace(
      /<script[\s\S]*?<\/script>/gi,
      ' '
    )
    .replace(
      /<style[\s\S]*?<\/style>/gi,
      ' '
    )
    .replace(
      /<noscript[\s\S]*?<\/noscript>/gi,
      ' '
    )
    .replace(
      /<!--[\s\S]*?-->/g,
      ' '
    )

    // Preserve rough structure
    .replace(
      /<\/(p|div|section|article|li|h1|h2|h3|h4|h5|tr|table)>/gi,
      '\n'
    )
    .replace(
      /<br\s*\/?>/gi,
      '\n'
    )

    // Remove remaining tags
    .replace(
      /<[^>]+>/g,
      ' '
    )

    // Normalize whitespace
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
}


// ------------------------------------------------------------
// Source metadata
// ------------------------------------------------------------

const source =
  $('Define TCM Source').item.json;


// ------------------------------------------------------------
// Prepare complete source text
//
// Important:
// We intentionally do NOT make assumptions about provider-specific
// section names or plant-specific wording.
//
// Extraction and validation downstream decide what information
// is actually supported.
// ------------------------------------------------------------

const sourceText =
  htmlToText(html);


// ------------------------------------------------------------
// Output
// ------------------------------------------------------------

return {
  json: {

    source_metadata: {

      plant:
        source.plant ?? null,

      chinese_name:
        source.chinese_name ?? null,

      pinyin:
        source.pinyin ?? null,

      latin_drug_name:
        source.latin_drug_name ?? null,

      source_type:
        source.source_type ??
        'herbal_database',

      source_name:
        source.source_name ??
        'Approved TCM Source',

      medical_system:
        source.medical_system ??
        'tcm',

      document_type:
        source.document_type ??
        'traditional herbal profile',

      source_url:
        source.source_url ?? null
    },


    source_stats: {

      source_text_length:
        sourceText.length
    },


    // Generic source text.
    // No provider-specific interpretation happens here.
    source_text:
      sourceText
  }
};

const targetSchema = {
  identity: {
    chinese_name: null,
    english_name: null,
    latin_drug_name: null,
    medicinal_group: null,
    botanical_source: null,
    family: null,
    plant_part: null
  },

  tcm_properties: {
    nature: null,
    flavors: [],
    meridian_affinity: []
  },

  traditional_actions: [
    {
      action: null,
      source_quote: null
    }
  ],

  traditional_indications: [
    {
      source_wording: null,
      source_quote: null
    }
  ],

  safety: {
    cautions: [
      {
        description: null,
        source_quote: null
      }
    ],

    interaction_warnings: [
      {
        description: null,
        source_quote: null
      }
    ],

    adverse_effects: [
      {
        description: null,
        source_quote: null
      }
    ],

    other_safety_notes: [
      {
        description: null,
        source_quote: null
      }
    ]
  },

  uncertainties: []
};

const rules = [
  'Use only information explicitly supported by the supplied approved source text.',
  'Do not use outside knowledge.',
  'Do not infer therapeutic efficacy.',
  'Preserve Traditional Chinese Medicine terminology.',
  'Do not translate traditional TCM concepts into Western biomedical indications.',
  'Do not create cross-cultural mappings in this extraction step.',
  'If information is unsupported, use null for scalar fields and [] for list fields.',
  'Every source_quote must be copied exactly as one contiguous substring from the supplied source text.',
  'Never paraphrase, combine passages, normalize wording, or add ellipses inside source_quote.',
  'Keep source_quote short and directly relevant.'
];

const sourceText =
  String(
    $json.source_text ?? ''
  ).trim();

return {
  json: {
    source_metadata: $json.source_metadata,
    schema_version: 'phythera_tcm_v1',

    extraction_config: {
      rules,
      target_schema: targetSchema
    },

    source_text: sourceText,

  }
};

const context = $('Define TCM Output Schema').item.json;

const errors = [];
const warnings = [];

// --------------------------------------------------
// 1. Normalize text conservatively
// --------------------------------------------------

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/\u00AD/g, '')
    .replace(/([A-Za-z])-\s*\n\s*([A-Za-z])/g, '$1-$2')
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[‐-‒–—−]/g, '-')
    .replace(/\u00A0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

// --------------------------------------------------
// 2. Remove possible Markdown fences
// --------------------------------------------------

function cleanJsonString(value) {
  return String(value ?? '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// --------------------------------------------------
// 3. Parse AI output
// --------------------------------------------------

let extractedData = null;

try {
  extractedData = JSON.parse(
    cleanJsonString($json.text)
  );
} catch (error) {
  errors.push({
    type: 'json_parse_error',
    path: '$',
    message: error.message
  });
}

// --------------------------------------------------
// 4. Validate schema structure
// --------------------------------------------------

function validateStructure(schema, value, path = '$') {

  if (Array.isArray(schema)) {

    if (!Array.isArray(value)) {
      errors.push({
        type: 'type_mismatch',
        path,
        message: 'Expected array.'
      });
      return;
    }

    if (schema.length > 0) {
      for (let i = 0; i < value.length; i++) {
        validateStructure(
          schema[0],
          value[i],
          `${path}[${i}]`
        );
      }
    }

    return;
  }

  if (
    schema !== null &&
    typeof schema === 'object'
  ) {

    if (
      value === null ||
      typeof value !== 'object' ||
      Array.isArray(value)
    ) {
      errors.push({
        type: 'type_mismatch',
        path,
        message: 'Expected object.'
      });
      return;
    }

    const schemaKeys = Object.keys(schema);
    const valueKeys = Object.keys(value);

    for (const key of schemaKeys) {
      if (!(key in value)) {
        errors.push({
          type: 'missing_key',
          path: `${path}.${key}`,
          message: `Missing required key: ${key}`
        });
      } else {
        validateStructure(
          schema[key],
          value[key],
          `${path}.${key}`
        );
      }
    }

    for (const key of valueKeys) {
      if (!(key in schema)) {
        errors.push({
          type: 'unexpected_key',
          path: `${path}.${key}`,
          message: `Unexpected key: ${key}`
        });
      }
    }

    return;
  }

  // null in the template = scalar value or null
  if (
    value !== null &&
    typeof value === 'object'
  ) {
    errors.push({
      type: 'type_mismatch',
      path,
      message: 'Expected scalar value or null.'
    });
  }
}

// --------------------------------------------------
// 5. Validate source quotes
// --------------------------------------------------

function checkQuoteGrounding(
  value,
  normalizedSource,
  path = '$'
) {

  if (Array.isArray(value)) {
    value.forEach((child, index) =>
      checkQuoteGrounding(
        child,
        normalizedSource,
        `${path}[${index}]`
      )
    );

    return;
  }

  if (
    typeof value === 'object' &&
    value !== null
  ) {

    for (const [key, child] of Object.entries(value)) {

      if (
        key === 'source_quote' &&
        typeof child === 'string' &&
        child.trim().length > 0
      ) {

        const normalizedQuote =
          normalizeText(child);

        if (
          !normalizedSource.includes(
            normalizedQuote
          )
        ) {
          errors.push({
            type: 'ungrounded_source_quote',
            path: `${path}.${key}`,
            message:
              'Quoted evidence could not be found verbatim in the supplied source text.'
          });
        }

        if (child.length > 350) {
          warnings.push({
            type: 'long_source_quote',
            path: `${path}.${key}`,
            message:
              'Source quote is longer than 350 characters.'
          });
        }
      }

      checkQuoteGrounding(
        child,
        normalizedSource,
        `${path}.${key}`
      );
    }
  }
}

// --------------------------------------------------
// 6. Ground identity + TCM property values
// --------------------------------------------------

function checkScalarGrounding(
  value,
  normalizedSource,
  path
) {

  if (
    typeof value === 'string' &&
    value.trim().length > 0
  ) {

    const normalizedValue =
      normalizeText(value);

    if (
      !normalizedSource.includes(
        normalizedValue
      )
    ) {
      errors.push({
        type: 'ungrounded_value',
        path,
        message:
          'Extracted value could not be found in the supplied source text.'
      });
    }
  }
}

function checkIdentityGrounding(
  data,
  normalizedSource
) {

  const identity =
    data?.identity ?? {};

  for (
    const [key, value]
    of Object.entries(identity)
  ) {
    checkScalarGrounding(
      value,
      normalizedSource,
      `$.identity.${key}`
    );
  }

  const properties =
    data?.tcm_properties ?? {};

  checkScalarGrounding(
    properties.nature,
    normalizedSource,
    '$.tcm_properties.nature'
  );

  for (
    const [index, flavor]
    of (properties.flavors ?? []).entries()
  ) {
    checkScalarGrounding(
      flavor,
      normalizedSource,
      `$.tcm_properties.flavors[${index}]`
    );
  }

  for (
    const [index, meridian]
    of (properties.meridian_affinity ?? []).entries()
  ) {
    checkScalarGrounding(
      meridian,
      normalizedSource,
      `$.tcm_properties.meridian_affinity[${index}]`
    );
  }
}

// --------------------------------------------------
// 7. Run validation
// --------------------------------------------------

if (extractedData !== null) {

  validateStructure(
    context.extraction_config.target_schema,
    extractedData
  );

  const normalizedSource =
    normalizeText(context.source_text);

  checkQuoteGrounding(
    extractedData,
    normalizedSource
  );

  checkIdentityGrounding(
    extractedData,
    normalizedSource
  );
}

// --------------------------------------------------
// 8. Determine status
// --------------------------------------------------

let status = 'pass';

if (errors.length > 0) {
  status = 'fail';
} else if (warnings.length > 0) {
  status = 'warning';
}

// --------------------------------------------------
// 9. Output
// --------------------------------------------------

return {
  json: {
    source_metadata:
      context.source_metadata,

    schema_version:
      context.schema_version,

    validation: {
      status,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    },

    extracted_data:
      extractedData
  }
};

const validated = $json;


// ============================================================
// 1. Stop if validation failed
// ============================================================

if (
  validated.validation?.status === 'fail'
) {
  throw new Error(
    'Cannot assemble TCM profile because validation failed.'
  );
}


// ============================================================
// 2. Convenience references
// ============================================================

const sourceMetadata =
  validated.source_metadata ?? {};

const extractedData =
  validated.extracted_data ?? {};

const identity =
  extractedData.identity ?? {};

const tcmProperties =
  extractedData.tcm_properties ?? {};

const traditionalActions =
  extractedData.traditional_actions ?? [];

const traditionalIndications =
  extractedData.traditional_indications ?? [];

const safety =
  extractedData.safety ?? {};

const uncertainties =
  extractedData.uncertainties ?? [];


// ============================================================
// 3. Determine extraction status
// ============================================================

let extractionStatus =
  'validated';

if (
  validated.validation?.status === 'warning'
) {
  extractionStatus =
    'validated_with_warnings';
}


// ============================================================
// 4. Build normalized TCM profile
// ============================================================

return {
  json: {

    // --------------------------------------------------------
    // Profile metadata
    // --------------------------------------------------------

    profile_metadata: {

      profile_type:
        'TCM',

      schema_version:
        validated.schema_version ??
        'phythera_tcm_v1',

      extraction_status:
        extractionStatus,


      // ------------------------------------------------------
      // Plant identity
      // Prefer orchestrator/source metadata.
      // Fall back to values extracted from the TCM source.
      // ------------------------------------------------------

      plant:
        sourceMetadata.plant ??
        identity.botanical_source ??
        null,

      chinese_name:
        sourceMetadata.chinese_name ??
        identity.chinese_name ??
        null,

      pinyin:
        sourceMetadata.pinyin ??
        null,

      latin_drug_name:
        sourceMetadata.latin_drug_name ??
        identity.latin_drug_name ??
        null,


      // ------------------------------------------------------
      // Source provenance
      // ------------------------------------------------------

      source_type:
        validated.source_metadata?.source_type ??
        'traditional_source',

      source_name:
        sourceMetadata.source_name ??
        null,

      medical_system:
        sourceMetadata.medical_system ??
        'tcm',

      document_type:
        sourceMetadata.document_type ??
        'traditional herbal profile',

      source_url:
        sourceMetadata.source_url ??
        null
    },


    // ========================================================
    // 5. Extracted identity
    // ========================================================

    identity: {

      chinese_name:
        identity.chinese_name ??
        null,

      english_name:
        identity.english_name ??
        null,

      latin_drug_name:
        identity.latin_drug_name ??
        null,

      medicinal_group:
        identity.medicinal_group ??
        null,

      botanical_source:
        identity.botanical_source ??
        null,

      family:
        identity.family ??
        null,

      plant_part:
        identity.plant_part ??
        null
    },


    // ========================================================
    // 6. TCM properties
    // ========================================================

    tcm_properties: {

      nature:
        tcmProperties.nature ??
        null,

      flavors:
        Array.isArray(
          tcmProperties.flavors
        )
          ? tcmProperties.flavors
          : [],

      meridian_affinity:
        Array.isArray(
          tcmProperties.meridian_affinity
        )
          ? tcmProperties.meridian_affinity
          : []
    },


    // ========================================================
    // 7. Traditional actions
    // ========================================================

    traditional_actions:
      Array.isArray(
        traditionalActions
      )
        ? traditionalActions
        : [],


    // ========================================================
    // 8. Traditional indications
    // ========================================================

    traditional_indications:
      Array.isArray(
        traditionalIndications
      )
        ? traditionalIndications
        : [],


    // ========================================================
    // 9. Safety
    // ========================================================

    safety: {

      cautions:
        Array.isArray(
          safety.cautions
        )
          ? safety.cautions
          : [],

      interaction_warnings:
        Array.isArray(
          safety.interaction_warnings
        )
          ? safety.interaction_warnings
          : [],

      adverse_effects:
        Array.isArray(
          safety.adverse_effects
        )
          ? safety.adverse_effects
          : [],

      other_safety_notes:
        Array.isArray(
          safety.other_safety_notes
        )
          ? safety.other_safety_notes
          : []
    },


    // ========================================================
    // 10. Uncertainties
    // ========================================================

    uncertainties:
      Array.isArray(
        uncertainties
      )
        ? uncertainties
        : [],


    // ========================================================
    // 11. Validation summary
    // ========================================================

    validation_summary: {

      status:
        validated.validation?.status ??
        'unknown',

      error_count:
        validated.validation?.error_count ??
        0,

      warning_count:
        validated.validation?.warning_count ??
        0,

      errors:
        Array.isArray(
          validated.validation?.errors
        )
          ? validated.validation.errors
          : [],

      warnings:
        Array.isArray(
          validated.validation?.warnings
        )
          ? validated.validation.warnings
          : []
    }
  }
};

