const input = $json;

const authorized =
  input.source_policy_checked === true &&
  input.automated_retrieval_authorized === true;

if (!authorized) {
  throw new Error(
    'Automated TCM retrieval blocked: explicit source authorization is missing.'
  );
}

return [
  {
    json: input
  }
];
